// Core tests: the 15 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC. Every expected value below was computed by hand from the SPEC's
// rules; the hand derivations are listed in AUTHOR-CHECK.md, and the
// appendix table was independently recomputed with exact rational
// arithmetic (Python fractions) before being transcribed here.

import assert from "node:assert/strict";
import test from "node:test";
import {
  APPENDIX_PREMIUMS,
  GRADE_AMOUNTS,
  formatAmount,
  gradeForSalary,
  run,
} from "../public/js/core/nhi-premium.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

// The SPEC appendix table, transcribed from SPEC section 3 and checked
// against the pinned formulas with an independent exact-rational
// recomputation: [selfPremium, employerPremium, governmentPremium].
