test("appendix: all 58 grades match the SPEC appendix premium table", () => {
  assert.equal(GRADE_AMOUNTS.length, 58);
  assert.equal(APPENDIX_PREMIUMS.length, 58);
  assert.deepEqual(APPENDIX_PREMIUMS, APPENDIX_EXPECTED);
  for (let grade = 1; grade <= 58; grade += 1) {
    const outcome = run({
      monthlySalary: String(GRADE_AMOUNTS[grade - 1]),
      dependents: "0",
    });
    assert.equal(outcome.ok, true, `grade ${grade} should succeed`);
    const [self, employer, government] = APPENDIX_EXPECTED[grade - 1];
    assert.equal(outcome.result.grade, grade);
    assert.equal(outcome.result.insuredAmount, GRADE_AMOUNTS[grade - 1]);
    assert.equal(outcome.result.selfPremium, self, `grade ${grade} selfPremium`);
    assert.equal(outcome.result.dependentPremiumEach, self, `grade ${grade} dependentPremiumEach`);
    assert.equal(outcome.result.employerPremium, employer, `grade ${grade} employerPremium`);
    assert.equal(outcome.result.governmentPremium, government, `grade ${grade} governmentPremium`);
  }
});

test("grade boundaries: each grade amount takes that grade, amount + 1 takes the next", () => {
  for (let grade = 1; grade <= 58; grade += 1) {
    const amount = GRADE_AMOUNTS[grade - 1];
    assert.equal(
      gradeForSalary(amount),
      grade,
      `salary ${amount} must be grade ${grade}`,
    );
    if (grade < 58) {
      assert.equal(
        gradeForSalary(amount + 1),
        grade + 1,
        `salary ${amount + 1} must be grade ${grade + 1}`,
      );
    }
  }
  assert.equal(gradeForSalary(1), 1);
  assert.equal(gradeForSalary(29499), 1);
  assert.equal(gradeForSalary(29500), 1);
  assert.equal(gradeForSalary(29501), 2);
  assert.equal(gradeForSalary(313000), 58);
  assert.equal(gradeForSalary(313001), 58);
  assert.equal(gradeForSalary(99999999), 58);
});

test("dependents 3 and 4 give the same totals but differ on the cap flag; 99 is legal, 100 is RANGE", () => {
  const base = { monthlySalary: "42100", dependents: "3" };
  const three = run(base);
  const four = run({ ...base, dependents: "4" });
  assert.equal(three.ok, true);
  assert.equal(four.ok, true);
  assert.equal(four.result.employeeTotalPremium, three.result.employeeTotalPremium);
  assert.equal(four.result.dependentsCharged, 3);
  assert.equal(three.result.dependentsCapped, false);
  assert.equal(four.result.dependentsCapped, true);
  const many = run({ ...base, dependents: "99" });
  assert.equal(many.ok, true);
  assert.equal(many.result.employeeTotalPremium, three.result.employeeTotalPremium);
  assert.equal(many.result.dependentsCapped, true);
  assert.deepEqual(run({ ...base, dependents: "100" }).error, {
    code: "RANGE",
    field: "dependents",
    row: null,
  });
});

test("float trap: the grade-1 per-person premium is 458, and the grade-38 premium is 2327, not what naive float paths give", () => {
  // Grade 1: the exact per-person premium is 457.545, but the binary
  // float 29500 * (5.17/100) * (30/100) is 457.54499999999996 — below
  // the exact tie, so it even loses the second decimal
  // (toFixed(2) gives "457.54", not "457.55"). The core uses exact
  // integer arithmetic and returns 458.
  const floatPath = 29500 * (5.17 / 100) * (30 / 100);
  assert.ok(floatPath < 457.545);
  assert.equal(floatPath.toFixed(2), "457.54");
  const grade1 = run({ monthlySalary: "29500", dependents: "0" });
  assert.equal(grade1.ok, true);
  assert.equal(grade1.result.selfPremium, 458);
  // Grade 38: the exact premium is 2326.5, rounded half up to 2327,
  // but the same float path rounds down to 2326 — a genuine wrong
  // integer from floating point, not just a lost decimal.
  const float38 = 150000 * (5.17 / 100) * (30 / 100);
  assert.ok(float38 < 2326.5);
  assert.equal(Math.round(float38), 2326);
  const grade38 = run({ monthlySalary: "150000", dependents: "0" });
  assert.equal(grade38.ok, true);
  assert.equal(grade38.result.selfPremium, 2327);
});

test("half-up discriminator: 150,000 gives exactly 2326.5, rounded up to 2327", () => {
  // 150000 * 1551 / 100000 = 2326.5 exactly; half-up rounds to 2327
  // (banker's rounding would give 2326).
  const outcome = run({ monthlySalary: "150000", dependents: "0" });
  assert.equal(outcome.ok, true);
  assert.equal(outcome.result.selfPremium, 2327);
});

test("integer grammar: signs, exponents, commas, spaces, decimals and leading zeros are INTEGER_FORMAT", () => {
  const base = { monthlySalary: "45000", dependents: "0" };
  for (const bad of ["-45000", "+45000", "4.5e4", "45,000", "45000 ", " 45000", "45000.0", "00", "01", "045000"]) {
    assert.deepEqual(run({ ...base, monthlySalary: bad }).error, {
      code: "INTEGER_FORMAT",
      field: "monthlySalary",
      row: null,
    });
  }
  for (const bad of ["-1", "1.0", "01", "00"]) {
    assert.deepEqual(run({ ...base, dependents: bad }).error, {
      code: "INTEGER_FORMAT",
      field: "dependents",
      row: null,
    });
  }
  // "0" itself is valid grammar for dependents (range 0-99).
  assert.equal(run({ ...base, dependents: "0" }).ok, true);
  // A leading zero is the only grammar failure for "0" as salary:
  // "0" parses but is out of range.
  assert.deepEqual(run({ ...base, monthlySalary: "0" }).error, {
    code: "RANGE",
    field: "monthlySalary",
    row: null,
  });
});

test("capacity and unicode: a 9-unit value is INPUT_LIMIT; a lone surrogate is UNICODE", () => {
  const base = { monthlySalary: "45000", dependents: "0" };
  assert.deepEqual(run({ ...base, monthlySalary: "100000000" }).error, {
    code: "INPUT_LIMIT",
    field: "monthlySalary",
    row: null,
  });
  assert.deepEqual(run({ ...base, dependents: "100000000" }).error, {
    code: "INPUT_LIMIT",
    field: "dependents",
    row: null,
  });
  // INPUT_LIMIT precedes grammar and range checks.
  assert.deepEqual(run({ ...base, monthlySalary: "99999999.5" }).error, {
    code: "INPUT_LIMIT",
    field: "monthlySalary",
    row: null,
  });
  assert.deepEqual(run({ ...base, monthlySalary: "\uD800" }).error, {
    code: "UNICODE",
    field: "monthlySalary",
    row: null,
  });
  assert.deepEqual(run({ ...base, dependents: "\uD800" }).error, {
    code: "UNICODE",
    field: "dependents",
    row: null,
  });
  assert.deepEqual(run({ ...base, monthlySalary: "" }).error, {
    code: "EMPTY",
    field: "monthlySalary",
    row: null,
  });
  assert.deepEqual(run({ ...base, dependents: "" }).error, {
    code: "EMPTY",
    field: "dependents",
    row: null,
  });
});

test("salary range: 1 succeeds, 99999999 succeeds, 100000000 is INPUT_LIMIT", () => {
  assert.equal(run({ monthlySalary: "1", dependents: "0" }).ok, true);
  assert.equal(run({ monthlySalary: "1", dependents: "0" }).result.grade, 1);
  assert.equal(run({ monthlySalary: "99999999", dependents: "0" }).ok, true);
  assert.equal(run({ monthlySalary: "99999999", dependents: "0" }).result.grade, 58);
});

test("the first field in the fixed order reports first", () => {
  const base = { monthlySalary: "45000", dependents: "0" };
  assert.deepEqual(run({ monthlySalary: "", dependents: "x" }).error, {
    code: "EMPTY",
    field: "monthlySalary",
    row: null,
  });
  assert.deepEqual(run({ monthlySalary: "45000.5", dependents: "1.5" }).error, {
    code: "INTEGER_FORMAT",
    field: "monthlySalary",
    row: null,
  });
  assert.deepEqual(run({ monthlySalary: "100000000", dependents: "100000000" }).error, {
    code: "INPUT_LIMIT",
    field: "monthlySalary",
    row: null,
  });
});

test("schema: extra key, missing key, wrong type, array, null, accessor and symbol key are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  const base = { monthlySalary: "45000", dependents: "0" };
  assert.deepEqual(run({ ...base, extra: "1" }).error, schema);
  const missing = { ...base };
  delete missing.dependents;
  assert.deepEqual(run(missing).error, schema);
  assert.deepEqual(run({ ...base, monthlySalary: 45000 }).error, schema);
  assert.deepEqual(run({ ...base, dependents: null }).error, schema);
  assert.deepEqual(run(["45000", "0"]).error, schema);
  assert.deepEqual(run(null).error, schema);
  assert.deepEqual(run("45000").error, schema);
  const withGetter = { ...base };
  Object.defineProperty(withGetter, "monthlySalary", {
    enumerable: true,
    get() {
      return "45000";
    },
  });
  assert.deepEqual(run(withGetter).error, schema);
  const withSymbol = { ...base, [Symbol("extra")]: "1" };
  assert.deepEqual(run(withSymbol).error, schema);
  const stringObject = { ...base };
  stringObject.monthlySalary = new String("45000");
  assert.deepEqual(run(stringObject).error, schema);
});

test("property: employeeTotalPremium always equals selfPremium * (1 + dependentsCharged)", () => {
  for (let grade = 1; grade <= 58; grade += 1) {
    for (const dependents of ["0", "1", "2", "3", "4", "99"]) {
      const outcome = run({
        monthlySalary: String(GRADE_AMOUNTS[grade - 1]),
        dependents,
      });
      assert.equal(outcome.ok, true);
      assert.equal(
        outcome.result.employeeTotalPremium,
        outcome.result.selfPremium * (1 + outcome.result.dependentsCharged),
      );
      assert.equal(outcome.result.dependentPremiumEach, outcome.result.selfPremium);
    }
  }
});

test("property: premiums never decrease as the grade grows", () => {
  let previousSelf = -Infinity;
  let previousEmployer = -Infinity;
  let previousGovernment = -Infinity;
  for (let grade = 1; grade <= 58; grade += 1) {
    const outcome = run({ monthlySalary: String(GRADE_AMOUNTS[grade - 1]), dependents: "0" });
    assert.equal(outcome.ok, true);
    assert.ok(outcome.result.selfPremium >= previousSelf);
    assert.ok(outcome.result.employerPremium >= previousEmployer);
    assert.ok(outcome.result.governmentPremium >= previousGovernment);
    previousSelf = outcome.result.selfPremium;
    previousEmployer = outcome.result.employerPremium;
    previousGovernment = outcome.result.governmentPremium;
  }
});

test("the core does not mutate its input", () => {
  const input = { monthlySalary: "45000", dependents: "2" };
  const snapshot = JSON.stringify(input);
  const outcome = run(input);
  assert.equal(outcome.ok, true);
  assert.equal(JSON.stringify(input), snapshot);
  const bad = { monthlySalary: "45000.5", dependents: "0" };
  const badSnapshot = JSON.stringify(bad);
  assert.equal(run(bad).ok, false);
  assert.equal(JSON.stringify(bad), badSnapshot);
});

test("display formatting: amounts group thousands with commas", () => {
  assert.equal(formatAmount(0), "0");
  assert.equal(formatAmount(458), "458");
  assert.equal(formatAmount(1428), "1,428");
  assert.equal(formatAmount(15146), "15,146");
  assert.equal(formatAmount(313000), "313,000");
  assert.equal(formatAmount(99999999), "99,999,999");
});
